SELECT CASE WHEN status IN ('CLOSED', 'OPEN') THEN 'tier_1' ELSE 'other' END AS status_group, CASE WHEN account_type IN ('SAVINGS', 'CHECKING') THEN 'tier_1' ELSE 'other' END AS account_type_group, status, SUM(CASE WHEN account_type = 'CHECKING' THEN 1 ELSE 0 END) AS checking_count FROM accounts WHERE NOT ((customer_id IN (8, 22, 26, 38) AND opened_date <= '2024-11-01') OR customer_id IN (27, 36)) GROUP BY CASE WHEN status IN ('CLOSED', 'OPEN') THEN 'tier_1' ELSE 'other' END, CASE WHEN account_type IN ('SAVINGS', 'CHECKING') THEN 'tier_1' ELSE 'other' END, status;
